// AUTO-GENERATED from styles.css — do not edit. Regenerate with `npm run gen:css`.
export const css: string = "/*!\n * TourKit | MIT License\n * BEM blocks, themable via CSS custom properties.\n *\n * Default look: light surface with a teal accent (matches light host pages).\n * A dark graphite variant is available via `theme: \"dark\"`; `theme: \"auto\"`\n * follows prefers-color-scheme.\n *\n * The version is intentionally absent here: scripts/copy-styles.mjs stamps it\n * into dist/styles.css at build time. Keeping the source free of it means the\n * committed css.generated.ts (embedded for `sitetourkit/inject-styles`) never\n * drifts when the package version is bumped.\n */\n\n.tk-root {\n  --tk-z: 99999;\n  --tk-overlay-color: #05070a;\n  --tk-overlay-opacity: 0.5;\n  --tk-radius: 14px;\n\n  /* Surface & text (default: light — matches light host pages).\n     Contrast: muted ≥ 4.5:1 on white, white on accent ≥ 4.5:1 (axe serious). */\n  --tk-surface: #ffffff;\n  --tk-text: #181b20;\n  --tk-text-secondary: #454b55;\n  --tk-text-muted: #5d6673;\n  --tk-border: rgb(24 27 32 / 0.1);\n  --tk-bullet: rgb(24 27 32 / 0.18);\n  --tk-shadow:\n    0 0 0 1px rgb(24 27 32 / 0.06), 0 16px 40px rgb(24 27 32 / 0.16),\n    0 4px 12px rgb(24 27 32 / 0.08);\n\n  /* Accent: teal — intentionally not the generic \"AI purple/blue\" */\n  --tk-accent: #0f766e;\n  --tk-accent-hover: #115e59;\n  --tk-accent-contrast: #ffffff;\n  --tk-glow: rgb(15 118 110 / 0.3);\n\n  /* Spotlight ring: transparent in the light theme (clean look);\n     the dark theme brightens it for a stronger highlight. */\n  --tk-spotlight-ring: transparent;\n  --tk-spotlight-ring-width: 0;\n  --tk-spotlight-glow: transparent;\n\n  --tk-font: system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n  --tk-tooltip-max-width: 360px;\n  --tk-transition: 180ms cubic-bezier(0.4, 0, 0.2, 1);\n\n  position: fixed;\n  inset: 0;\n  z-index: var(--tk-z);\n  pointer-events: none;\n  opacity: 0;\n  transition: opacity var(--tk-transition);\n  font-family: var(--tk-font);\n}\n\n.tk-root,\n.tk-root * {\n  box-sizing: border-box;\n}\n\n.tk-root--visible {\n  opacity: 1;\n}\n\n/* Dark variant (graphite + teal): for dark host pages — `theme: \"dark\"`.\n   `theme: \"light\"` needs no rules: light is the default.\n   Keep in sync with the `theme: \"auto\"` dark half below. */\n.tk-root[data-tk-theme=\"dark\"] {\n  --tk-surface: #15171c;\n  --tk-text: #f4f6f9;\n  --tk-text-secondary: #c3cad6;\n  --tk-text-muted: #8f98a6;\n  --tk-border: rgb(255 255 255 / 0.1);\n  --tk-bullet: rgb(255 255 255 / 0.24);\n  --tk-shadow:\n    0 0 0 1px rgb(255 255 255 / 0.07), 0 16px 40px rgb(0 0 0 / 0.45), 0 4px 12px rgb(0 0 0 / 0.35);\n  --tk-accent: #2dd4bf;\n  --tk-accent-hover: #5eead4;\n  --tk-accent-contrast: #06231f;\n  --tk-glow: rgb(45 212 191 / 0.45);\n\n  /* Stronger dimming + a bright glowing ring around the highlighted element */\n  --tk-overlay-opacity: 0.68;\n  --tk-spotlight-ring: rgb(94 234 212 / 0.9);\n  --tk-spotlight-ring-width: 2px;\n  --tk-spotlight-glow: rgb(45 212 191 / 0.55);\n}\n\n/* Auto theme: follows the OS preference (light stays the default look). */\n@media (prefers-color-scheme: dark) {\n  .tk-root[data-tk-theme=\"auto\"] {\n    --tk-surface: #15171c;\n    --tk-text: #f4f6f9;\n    --tk-text-secondary: #c3cad6;\n    --tk-text-muted: #8f98a6;\n    --tk-border: rgb(255 255 255 / 0.1);\n    --tk-bullet: rgb(255 255 255 / 0.24);\n    --tk-shadow:\n      0 0 0 1px rgb(255 255 255 / 0.07), 0 16px 40px rgb(0 0 0 / 0.45), 0 4px 12px rgb(0 0 0 / 0.35);\n    --tk-accent: #2dd4bf;\n    --tk-accent-hover: #5eead4;\n    --tk-accent-contrast: #06231f;\n    --tk-glow: rgb(45 212 191 / 0.45);\n\n    --tk-overlay-opacity: 0.68;\n    --tk-spotlight-ring: rgb(94 234 212 / 0.9);\n    --tk-spotlight-ring-width: 2px;\n    --tk-spotlight-glow: rgb(45 212 191 / 0.55);\n  }\n}\n\n/* ---------------------------------- Overlay -------------------------------- */\n\n.tk-overlay {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  pointer-events: none;\n}\n\n/* Only the painted (dimmed) area receives clicks; the cutout lets events through. */\n.tk-overlay__path {\n  pointer-events: auto;\n  fill: var(--tk-overlay-color);\n  fill-opacity: var(--tk-overlay-opacity);\n}\n\n/* Themable outline of the spotlight cutouts (bright in the dark theme). */\n.tk-overlay__ring {\n  pointer-events: none;\n  fill: none;\n  stroke: var(--tk-spotlight-ring);\n  stroke-width: var(--tk-spotlight-ring-width);\n  filter: drop-shadow(0 0 6px var(--tk-spotlight-glow));\n}\n\n.tk-interaction-guard {\n  position: fixed;\n  pointer-events: auto;\n}\n\n/* ---------------------------------- Tooltip -------------------------------- */\n\n.tk-tooltip {\n  position: fixed;\n  pointer-events: auto;\n  /* Never wider than the viewport minus the solver's 8px side padding —\n     keeps narrow phones (320-390px) from overflowing. */\n  max-width: min(var(--tk-tooltip-max-width), calc(100vw - 16px));\n  min-width: min(260px, calc(100vw - 16px));\n  /* Same guarantee vertically: a long step on a short viewport must never\n     push its header (title + close) off screen. The content area scrolls\n     instead — see .tk-tooltip__content. */\n  max-height: calc(100dvh - 16px);\n  background: var(--tk-surface);\n  color: var(--tk-text);\n  border-radius: var(--tk-radius);\n  box-shadow: var(--tk-shadow);\n  outline: none;\n  font-size: 14px;\n  line-height: 1.55;\n}\n\n.tk-tooltip__arrow {\n  position: absolute;\n  width: 14px;\n  height: 14px;\n  background: var(--tk-surface);\n  transform: rotate(45deg);\n}\n\n/* The side names where the tooltip sits relative to the target,\n   so the arrow attaches to the opposite edge of the tooltip. */\n.tk-tooltip__arrow[data-side=\"bottom\"] {\n  top: -7px;\n}\n.tk-tooltip__arrow[data-side=\"top\"] {\n  bottom: -7px;\n}\n.tk-tooltip__arrow[data-side=\"right\"] {\n  left: -7px;\n}\n.tk-tooltip__arrow[data-side=\"left\"] {\n  right: -7px;\n}\n\n/* Column layout so the content can shrink while header, meta row and footer\n   keep their intrinsic height. `overflow` stays on the content: the arrow is\n   an absolutely positioned sibling that sticks out of the tooltip box and\n   would be clipped by a scroll container on .tk-tooltip itself. */\n.tk-tooltip__body {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  max-height: inherit;\n  border-radius: inherit;\n  background: inherit;\n}\n\n/* Everything except the content keeps its intrinsic height when the tooltip\n   hits its max-height — only the content scrolls. */\n.tk-tooltip__header,\n.tk-tooltip__once,\n.tk-tooltip__step-number,\n.tk-tooltip__progress,\n.tk-tooltip__footer {\n  flex-shrink: 0;\n}\n\n.tk-tooltip__header {\n  display: flex;\n  align-items: flex-start;\n  gap: 10px;\n  padding: 16px 18px 0;\n  min-height: 22px;\n}\n\n.tk-tooltip__title {\n  flex: 1;\n  margin: 0;\n  font-size: 15px;\n  font-weight: 600;\n  letter-spacing: -0.01em;\n  line-height: 1.4;\n}\n\n.tk-tooltip__close {\n  flex-shrink: 0;\n  margin-inline-start: auto;\n  width: 28px;\n  height: 28px;\n  margin-top: -5px;\n  margin-inline-end: -9px;\n  border: none;\n  background: transparent;\n  color: var(--tk-text-muted);\n  font-size: 19px;\n  line-height: 1;\n  border-radius: 8px;\n  cursor: pointer;\n  transition:\n    background-color var(--tk-transition),\n    color var(--tk-transition);\n}\n\n.tk-tooltip__close:hover {\n  color: var(--tk-text);\n  background: rgb(128 128 128 / 0.16);\n}\n\n.tk-tooltip__close:focus-visible {\n  outline: 2px solid var(--tk-accent);\n  outline-offset: 1px;\n}\n\n.tk-tooltip__content {\n  flex: 1 1 auto;\n  min-height: 0;\n  overflow-y: auto;\n  overscroll-behavior: contain;\n  padding: 8px 18px 16px;\n  color: var(--tk-text-secondary);\n}\n\n.tk-tooltip__header:has(+ .tk-tooltip__content:empty) {\n  padding-bottom: 16px;\n}\n\n.tk-tooltip__once {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 0 18px 12px;\n  font-size: 12.5px;\n  color: var(--tk-text-muted);\n  cursor: pointer;\n  user-select: none;\n}\n\n.tk-tooltip__once:hover {\n  color: var(--tk-text-secondary);\n}\n\n.tk-tooltip__once-box {\n  width: 14px;\n  height: 14px;\n  margin: 0;\n  cursor: pointer;\n  accent-color: var(--tk-accent);\n}\n\n.tk-tooltip__step-number {\n  padding: 0 18px 8px;\n  font-size: 11px;\n  font-weight: 500;\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n  color: var(--tk-text-muted);\n}\n\n/* Segmented progress: one segment per step. Completed segments are dimmed\n   accent, the current one is a glowing gradient that sweeps in — reads as\n   discrete steps rather than an intro.js-style continuous bar. */\n.tk-tooltip__progress {\n  display: flex;\n  gap: 3px;\n  margin: 0 18px 12px;\n  height: 4px;\n}\n\n.tk-tooltip__progress-seg {\n  flex: 1;\n  height: 100%;\n  border-radius: 999px;\n  background: var(--tk-bullet);\n  transition:\n    background-color var(--tk-transition),\n    opacity var(--tk-transition);\n}\n\n.tk-tooltip__progress-seg--done {\n  background: var(--tk-accent);\n  opacity: 0.45;\n}\n\n.tk-tooltip__progress-seg--current {\n  background: linear-gradient(90deg, var(--tk-accent), var(--tk-accent-hover));\n  box-shadow: 0 0 10px var(--tk-glow);\n  transform-origin: left;\n  animation:\n    tk-seg-fill 280ms cubic-bezier(0.4, 0, 0.2, 1),\n    tk-seg-glow 2.2s ease-in-out 280ms infinite alternate;\n}\n\n@keyframes tk-seg-fill {\n  from {\n    transform: scaleX(0.25);\n    opacity: 0.4;\n  }\n  to {\n    transform: scaleX(1);\n    opacity: 1;\n  }\n}\n\n@keyframes tk-seg-glow {\n  from {\n    box-shadow: 0 0 4px var(--tk-glow);\n  }\n  to {\n    box-shadow: 0 0 12px var(--tk-glow);\n  }\n}\n\n.tk-tooltip__footer {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px 12px;\n  /* Narrow screens: bullets and action buttons stack instead of squeezing. */\n  flex-wrap: wrap;\n  padding: 12px 18px 14px;\n  border-top: 1px solid var(--tk-border);\n}\n\n/* ------------------------------ Bullets (crumbs) --------------------------- */\n\n.tk-tooltip__bullets {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n  min-height: 26px;\n}\n\n.tk-tooltip__bullet {\n  position: relative;\n  width: 10px;\n  height: 10px;\n  padding: 0;\n  border: none;\n  border-radius: 999px;\n  background: var(--tk-bullet);\n  color: transparent;\n  font: inherit;\n  font-size: 0;\n  cursor: pointer;\n  transition:\n    width var(--tk-transition),\n    height var(--tk-transition),\n    background-color var(--tk-transition),\n    color var(--tk-transition),\n    font-size var(--tk-transition);\n}\n\n/* Invisible padding extends the hit target of small dots to ~24px. */\n.tk-tooltip__bullet::after {\n  content: \"\";\n  position: absolute;\n  inset: -7px;\n}\n\n.tk-tooltip__bullet:hover {\n  background: var(--tk-text-muted);\n}\n\n/* Active crumb: a large circle with the step number inside. */\n.tk-tooltip__bullet--active {\n  width: 26px;\n  height: 26px;\n  display: grid;\n  place-items: center;\n  background: var(--tk-accent);\n  color: var(--tk-accent-contrast);\n  font-size: 12px;\n  font-weight: 700;\n  cursor: default;\n}\n\n.tk-tooltip__bullet--active:hover {\n  background: var(--tk-accent);\n}\n\n.tk-tooltip__bullet:focus-visible {\n  outline: 2px solid var(--tk-accent);\n  outline-offset: 2px;\n}\n\n/* ---------------------------------- Buttons -------------------------------- */\n\n.tk-tooltip__actions {\n  display: flex;\n  gap: 8px;\n  margin-inline-start: auto;\n}\n\n.tk-button {\n  padding: 7px 14px;\n  border-radius: 9px;\n  border: 1px solid transparent;\n  font: inherit;\n  font-size: 13px;\n  font-weight: 600;\n  letter-spacing: 0.01em;\n  cursor: pointer;\n  transition:\n    background-color var(--tk-transition),\n    border-color var(--tk-transition);\n}\n\n.tk-button:focus-visible {\n  outline: 2px solid var(--tk-accent);\n  outline-offset: 1px;\n}\n\n.tk-button--primary {\n  background: var(--tk-accent);\n  color: var(--tk-accent-contrast);\n}\n\n.tk-button--primary:hover:not([disabled]) {\n  background: var(--tk-accent-hover);\n}\n\n.tk-button--ghost {\n  background: transparent;\n  border-color: var(--tk-border);\n  color: var(--tk-text);\n  font-weight: 500;\n}\n\n.tk-button--ghost:hover:not([disabled]) {\n  background: rgb(128 128 128 / 0.12);\n}\n\n.tk-button[disabled] {\n  opacity: 0.4;\n  cursor: default;\n}\n\n/* ----------------------------------- Hints --------------------------------- */\n\n.tk-hint {\n  position: fixed;\n  pointer-events: auto;\n  width: 18px;\n  height: 18px;\n  padding: 0;\n  border: none;\n  border-radius: 999px;\n  background: var(--tk-accent);\n  box-shadow: 0 0 0 3px var(--tk-glow);\n  cursor: pointer;\n  transform: translate(-50%, -50%);\n}\n\n.tk-hint__pulse {\n  position: absolute;\n  inset: 0;\n  border-radius: inherit;\n  background: inherit;\n  opacity: 0.5;\n  animation: tk-hint-ping 1.8s cubic-bezier(0, 0, 0.2, 1) infinite;\n  pointer-events: none;\n}\n\n@keyframes tk-hint-ping {\n  from {\n    transform: scale(1);\n    opacity: 0.5;\n  }\n  to {\n    transform: scale(2.2);\n    opacity: 0;\n  }\n}\n\n.tk-hint--hidden {\n  display: none;\n}\n\n.tk-hint:focus-visible {\n  outline: 2px solid var(--tk-accent);\n  outline-offset: 3px;\n}\n\n/* Invisible padding: expands the 18px marker to a ~38px hit target. */\n.tk-hint::after {\n  content: \"\";\n  position: absolute;\n  inset: -10px;\n  border-radius: inherit;\n}\n\n.tk-hint-popover {\n  position: fixed;\n  pointer-events: auto;\n  max-width: 300px;\n  min-width: 200px;\n  padding: 12px 14px;\n  background: var(--tk-surface);\n  color: var(--tk-text-secondary);\n  border-radius: var(--tk-radius);\n  box-shadow: var(--tk-shadow);\n  font-size: 13.5px;\n  line-height: 1.5;\n}\n\n.tk-hint-popover__button {\n  margin-top: 10px;\n}\n\n/* --------------------------------- Live region ----------------------------- */\n\n.tk-live {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  margin: -1px;\n  padding: 0;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  clip-path: inset(50%);\n  white-space: nowrap;\n  border: 0;\n}\n\n/* ------------------------------ Touch ergonomics --------------------------- */\n\n@media (pointer: coarse) {\n  .tk-button {\n    padding: 10px 16px;\n  }\n\n  .tk-tooltip__close {\n    width: 36px;\n    height: 36px;\n    margin-top: -8px;\n  }\n\n  .tk-tooltip__bullet::after {\n    inset: -9px;\n  }\n\n  .tk-hint {\n    width: 22px;\n    height: 22px;\n  }\n}\n\n/* ------------------- Forced colors (Windows High Contrast) ----------------- */\n\n@media (forced-colors: active) {\n  /* box-shadow is stripped in forced-colors mode — borders take over. */\n  .tk-tooltip,\n  .tk-hint-popover {\n    border: 1px solid CanvasText;\n  }\n\n  /* The arrow is a borderless rotated square; without its shadow it degrades\n     into a floating blob. The spotlight ring keeps pointing at the target. */\n  .tk-tooltip__arrow {\n    display: none;\n  }\n\n  /* Keep the dimming translucent: forced fills are opaque, but fill-opacity\n     is not on the forced list — an explicit pair preserves the see-through\n     scrim in both HC palettes. */\n  .tk-overlay__path {\n    forced-color-adjust: none;\n    fill: CanvasText;\n    fill-opacity: 0.4;\n  }\n\n  .tk-overlay__ring {\n    forced-color-adjust: none;\n    stroke: Highlight;\n    stroke-width: 3px;\n    filter: none;\n  }\n\n  .tk-button {\n    border: 1px solid ButtonText;\n  }\n\n  /* Color-only state indicators get explicit system colors. */\n  .tk-tooltip__bullet,\n  .tk-tooltip__progress-seg {\n    forced-color-adjust: none;\n    background: ButtonFace;\n    border: 1px solid ButtonText;\n  }\n\n  .tk-tooltip__bullet--active,\n  .tk-tooltip__progress-seg--done,\n  .tk-tooltip__progress-seg--current {\n    background: Highlight;\n    color: HighlightText;\n  }\n\n  .tk-tooltip__progress-seg--current {\n    box-shadow: none;\n    animation: none;\n  }\n\n  .tk-hint {\n    border: 2px solid ButtonText;\n  }\n\n  .tk-hint__pulse {\n    display: none;\n  }\n}\n\n/* ------------------------------- Reduced motion ---------------------------- */\n\n@media (prefers-reduced-motion: reduce) {\n  .tk-root,\n  .tk-tooltip__progress-seg,\n  .tk-tooltip__bullet,\n  .tk-tooltip__close,\n  .tk-button {\n    transition: none;\n  }\n\n  .tk-tooltip__progress-seg--current,\n  .tk-hint__pulse {\n    animation: none;\n  }\n}\n";
